#include "engine/Signatures.h"
#include <pl/memory/Signature.hpp>

namespace continuity_bedrock::engine {
static constexpr auto kModule = "libminecraftpe.so";

Addresses resolveAddresses() {
    Addresses a{};
    a.blockTessellatorGetTexture = pl::memory::resolveSignature(
        "FF C3 01 D1 FD 7B 02 A9 F9 1B 00 F9 F8 5F 04 A9 F6 57 05 A9 F4 4F 06 A9 FD 83 00 91 59 D0 3B D5 F3 03 05 AA F4 03 04 2A", kModule);
    a.blockTessellatorCacheGetBlock = pl::memory::resolveSignature(
        "FD 7B BB A9 F9 0B 00 F9 F8 5F 02 A9 F6 57 03 A9 F4 4F 04 A9 FD 03 00 91 F4 03 00 AA 00 00 40 F9", kModule);
    a.blockGraphicsGetTextureUv = pl::memory::resolveSignature(
        "FF 83 01 D1 FD 7B 02 A9 F8 5F 03 A9 F6 57 04 A9 F4 4F 05 A9 FD 83 00 91 58 D0 3B D5 F4 03 08 AA F7 03 00 AA 08 17 40 F9 A8 83 1F F8", kModule);
    a.useNewTessellation = pl::memory::resolveSignature(
        "FD 7B BE A9 F4 4F 01 A9 FD 03 00 91 F4 03 01 2A F3 03 00 AA DE 63 33 94", kModule);
    a.renderChunkBuilderBuild = pl::memory::resolveSignature(
        "E8 0F 19 FC FD 7B 01 A9 FC 6F 02 A9 FA 67 03 A9 F8 5F 04 A9 F6 57 05 A9 F4 4F 06 A9 FD 43 00 91 FF 43 2C D1", kModule);
    a.pipelineRun = pl::memory::resolveSignature(
        "FF 43 02 D1 FD 7B 05 A9 F8 5F 06 A9 F6 57 07 A9 F4 4F 08 A9 FD 43 01 91 57 D0 3B D5", kModule);

    // Side-face tessellators are the Bedrock extra-quad injection point used by
    // the plank-overlay POC. Patterns are validated against 1.26.52.3 and are
    // intentionally kept out of coreAddressesReady so base CTM can still load
    // if one future renderer build changes these functions.
    a.tessellateFaceNorth = pl::memory::resolveSignature(
        "? ? ? D1 ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? A9 ? ? ? F9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? 91 57 D0 3B D5 ? ? ? 91 F6 03 03 AA ? ? ? F9 F5 03 02 AA F4 03 00 AA F3 03 01 AA ? ? ? F8 ? ? ? 39 ? ? ? 39 1F 01 00 71 98 00 8A 9A ? ? ? 37 ? ? ? 39 ? ? ? 34 ? ? ? F9 ? ? ? B4 ? ? ? F9 ? ? ? 91 ? ? ? 91 ? ? ? 95 ? ? ? 14 ? ? ? F9 ? ? ? 91 ? ? ? 95 ? ? ? F9 ? ? ? 3D ? ? ? F9 ? ? ? 52 ? ? ? 3D ? ? ? 39 E0 03 13 AA ? ? ? 52 ? ? ? 94 ? ? ? 2D ? ? ? BD ? ? ? 2D ? ? ? BD ? ? ? BD 04 38 22 1E 61 38 21 1E ? ? ? BD A5 08 24 1E 04 08 24 1E C6 08 21 1E E7 08 21 1E ? ? ? BD 28 20 20 1E 4B 28 24 1E 49 28 25 1E 68 38 26 1E 6A 38 27 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? 39 ? ? ? 34 ? ? ? 91 E0 03 13 AA ? ? ? 94 ? ? ? BD ? ? ? BD ? ? ? BD ? ? ? 52 ? ? ? BD 2B 40 20 1E ? ? ? 39 ? ? ? 39 ? ? ? 91 E1 03 16 AA ? ? ? 71 08 15 9F 1A 1F 01 00 71 6C 1D 29 1E", kModule);
    a.tessellateFaceSouth = pl::memory::resolveSignature(
        "? ? ? D1 ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? A9 ? ? ? F9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? 91 57 D0 3B D5 ? ? ? 91 F6 03 03 AA ? ? ? F9 F5 03 02 AA F4 03 00 AA F3 03 01 AA ? ? ? F8 ? ? ? 39 ? ? ? 39 1F 01 00 71 98 00 8A 9A ? ? ? 37 ? ? ? 39 ? ? ? 34 ? ? ? F9 ? ? ? B4 ? ? ? F9 ? ? ? 91 ? ? ? 91 ? ? ? 95 ? ? ? 14 ? ? ? F9 ? ? ? 91 ? ? ? 95 ? ? ? F9 ? ? ? 3D ? ? ? F9 ? ? ? 52 ? ? ? 3D ? ? ? 39 E0 03 13 AA ? ? ? 52 ? ? ? 94 ? ? ? 2D ? ? ? BD ? ? ? 2D ? ? ? BD ? ? ? BD 04 38 22 1E 61 38 21 1E ? ? ? BD A5 08 24 1E 04 08 24 1E C6 08 21 1E E7 08 21 1E ? ? ? BD 28 20 20 1E 4A 28 24 1E 49 28 25 1E", kModule);
    a.tessellateFaceWest = pl::memory::resolveSignature(
        "? ? ? D1 ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? A9 ? ? ? F9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? 91 57 D0 3B D5 ? ? ? 91 F6 03 03 AA ? ? ? F9 F5 03 02 AA F4 03 00 AA F3 03 01 AA ? ? ? F8 ? ? ? 39 ? ? ? 39 1F 01 00 71 98 00 8A 9A ? ? ? 37 ? ? ? 39 ? ? ? 34 ? ? ? F9 ? ? ? B4 ? ? ? F9 ? ? ? 91 ? ? ? 91 ? ? ? 95 ? ? ? 14 ? ? ? F9 ? ? ? 91 ? ? ? 95 ? ? ? F9 ? ? ? 3D ? ? ? F9 ? ? ? 52 ? ? ? 3D ? ? ? 39 E0 03 13 AA ? ? ? 52 ? ? ? 94 ? ? ? 2D ? ? ? BD ? ? ? 2D ? ? ? BD ? ? ? BD 04 38 22 1E 61 38 21 1E ? ? ? BD A5 08 24 1E 04 08 24 1E C6 08 21 1E E7 08 21 1E ? ? ? BD 28 20 20 1E 4B 28 24 1E 49 28 25 1E 68 38 26 1E 6A 38 27 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? BD 48 20 20 1E ? ? ? 54 ? ? ? 39 ? ? ? 34 ? ? ? 91 E0 03 13 AA ? ? ? 94 ? ? ? BD ? ? ? BD ? ? ? BD ? ? ? 52 ? ? ? BD 2B 40 20 1E ? ? ? 39 ? ? ? 39 ? ? ? 91 E1 03 16 AA ? ? ? 71 08 15 9F 1A 1F 01 00 71 6D 1D 29 1E", kModule);
    a.tessellateFaceEast = pl::memory::resolveSignature(
        "? ? ? D1 ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? 6D ? ? ? A9 ? ? ? F9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? A9 ? ? ? 91 57 D0 3B D5 ? ? ? 91 F6 03 03 AA ? ? ? F9 F5 03 02 AA F4 03 00 AA F3 03 01 AA ? ? ? F8 ? ? ? 39 ? ? ? 39 1F 01 00 71 98 00 8A 9A ? ? ? 37 ? ? ? 39 ? ? ? 34 ? ? ? F9 ? ? ? B4 ? ? ? F9 ? ? ? 91 ? ? ? 91 ? ? ? 95 ? ? ? 14 ? ? ? F9 ? ? ? 91 ? ? ? 95 ? ? ? F9 ? ? ? 3D ? ? ? F9 ? ? ? 52 ? ? ? 3D ? ? ? 39 E0 03 13 AA ? ? ? 52 ? ? ? 94 ? ? ? 2D ? ? ? BD ? ? ? 2D ? ? ? BD ? ? ? BD 04 38 22 1E 61 38 21 1E ? ? ? BD A5 08 24 1E 04 08 24 1E C6 08 21 1E E7 08 21 1E ? ? ? BD 28 20 20 1E 4A 28 24 1E 48 28 25 1E", kModule);

    // TextureUVCoordinateSet has non-trivial internal state. The overlay POC
    // must clone it through Minecraft's own copy ctor/dtor before cropping UVs.
    a.textureUvCopyCtor = pl::memory::resolveSignature(
        "? ? ? A9 ? ? ? A9 FD 03 00 91 ? ? ? 3C ? ? ? 3D F4 03 01 AA F3 03 00 AA ? ? ? 3C ? ? ? 3D ? ? ? B9 ? ? ? B9 E8 03 01 AA", kModule);
    a.textureUvDtor = pl::memory::resolveSignature(
        "? ? ? 39 ? ? ? 37 C0 03 5F D6 ? ? ? F9 ? ? ? 15 ? ? ? 90", kModule);
    return a;
}

bool coreAddressesReady(const Addresses& a) {
    return a.blockTessellatorGetTexture && a.blockTessellatorCacheGetBlock && a.blockGraphicsGetTextureUv;
}
}
